<?php
declare(strict_types=1);
require_once __DIR__ . '/db.php';
function rss_trade_disable_stale_sources(): void{static $done=false;if($done)return;$done=true;try{db()->exec('UPDATE rss_sources rs INNER JOIN partner_rss pr ON pr.id=rs.source_ref_id SET rs.is_enabled=0,rs.updated_at=NOW() WHERE rs.source_type="partner_link" AND rs.is_enabled=1 AND (TRIM(COALESCE(pr.feed_url,""))="" OR COALESCE(pr.show_rss,pr.is_enabled,1)<>1 OR rs.feed_url<>pr.feed_url OR EXISTS (SELECT 1 FROM partner_rss newer WHERE newer.partner_site_id=pr.partner_site_id AND COALESCE(newer.show_rss,newer.is_enabled,1)=1 AND TRIM(COALESCE(newer.feed_url,""))<>"" AND (newer.updated_at>pr.updated_at OR (newer.updated_at=pr.updated_at AND newer.id>pr.id))))');}catch(Throwable $e){error_log('[rss] stale partner source cleanup skipped: '.$e->getMessage());}}
function rss_trade_candidate_pool(int $perSiteLimit=40,bool $requireImage=false,int $days=14): array{$perSiteLimit=max(1,min(200,$perSiteLimit));$days=max(1,min(365,$days));rss_trade_disable_stale_sources();try{$rows=db()->query('SELECT ps.id AS partner_site_id,pr.id AS partner_rss_id,pr.feed_url,pr.updated_at FROM partner_sites ps INNER JOIN partner_rss pr ON pr.partner_site_id=ps.id WHERE ps.is_enabled=1 AND COALESCE(pr.show_rss,pr.is_enabled,1)=1 AND TRIM(COALESCE(pr.feed_url,""))<>"" ORDER BY ps.id ASC,pr.updated_at DESC,pr.id DESC')->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){error_log('[rss] canonical partner RSS list failed: '.$e->getMessage());return [];}$feeds=[];foreach($rows as $r){$sid=(int)($r['partner_site_id']??0);if($sid<=0||isset($feeds[$sid]))continue;$feeds[$sid]=['rss_id'=>(int)($r['partner_rss_id']??0),'feed_url'=>trim((string)($r['feed_url']??''))];}if($feeds===[])return [];$siteIds=array_keys($feeds);shuffle($siteIds);$all=[];$seen=[];foreach($siteIds as $partnerSiteId){$f=$feeds[$partnerSiteId]??null;if(!is_array($f))continue;$rssId=(int)($f['rss_id']??0);$feedUrl=trim((string)($f['feed_url']??''));if($rssId<=0||$feedUrl==='')continue;try{$st=db()->prepare('SELECT id FROM rss_sources WHERE source_type="partner_link" AND source_ref_id=:rss_id AND feed_url=:feed_url AND is_enabled=1 ORDER BY id DESC LIMIT 1');$st->execute([':rss_id'=>$rssId,':feed_url'=>$feedUrl]);$sourceId=(int)($st->fetchColumn()?:0);if($sourceId<=0)continue;$imageClause=$requireImage?' AND COALESCE(NULLIF(TRIM(ri.image_url),""),"")<>""':'';$sql='SELECT ri.source_id,rs.name AS source_name,ri.title,ri.url,ri.guid,ri.published_at,ri.image_url FROM rss_items ri INNER JOIN rss_sources rs ON rs.id=ri.source_id WHERE ri.source_id=:source_id AND ri.published_at>=DATE_SUB(NOW(), INTERVAL '.$days.' DAY)'.$imageClause.' ORDER BY ri.published_at DESC,ri.id DESC LIMIT '.$perSiteLimit;$stmt=db()->prepare($sql);$stmt->execute([':source_id'=>$sourceId]);foreach($stmt->fetchAll(PDO::FETCH_ASSOC)?:[] as $row){$url=trim((string)($row['url']??''));$guid=trim((string)($row['guid']??''));$key=$url!==''?'url|'.mb_strtolower($url):($guid!==''?'guid|'.mb_strtolower($guid):'');if($key!==''&&isset($seen[$key]))continue;if($key!=='')$seen[$key]=true;$all[]=['title'=>(string)($row['title']??''),'link'=>$url,'guid'=>$guid,'published_at'=>(string)($row['published_at']??''),'image_url'=>trim((string)($row['image_url']??'')),'source_id'=>$sourceId,'source_name'=>(string)($row['source_name']??''),'partner_site_id'=>$partnerSiteId];}}catch(Throwable $e){error_log('[rss] canonical candidate fetch failed for partner '.$partnerSiteId.': '.$e->getMessage());}}if(count($all)>1)shuffle($all);return $all;}
